const TArray<FTCTutorialStep>& TCTutorialData::Steps()
{
	static const TArray<FTCTutorialStep> All = MakeSteps();
	return All;
}

FVector2D TCTutorialData::CellCentre(FIntPoint C) { return FVector2D((C.X + 0.5) * Cell, (C.Y + 0.5) * Cell); }

int32 TCTutorialData::StepOfGoal(const FString& Goal)
{
	const TArray<FTCTutorialStep>& All = Steps();
	for (int32 I = 0; I < All.Num(); I++) if (All[I].Goal.Equals(Goal, ESearchCase::CaseSensitive)) return I;
	return -1;
}

bool TCTutorialData::FindLine(const FString& Text, int32& OutStep, int32& OutLine)
{
	const TArray<FTCTutorialStep>& All = Steps();
	for (int32 I = 0; I < All.Num(); I++)
		for (int32 L = 0; L < All[I].Say.Num(); L++)
			if (All[I].Say[L].Equals(Text, ESearchCase::CaseSensitive)) { OutStep = I; OutLine = L; return true; }
	return false;
}

// ---------------------------------------------------------------------------------------------------------------------
// The lobby's Tutorial entry

const TCHAR* TCTutorialEntry::Label() { return TEXT("Tutorial"); }
const TCHAR* TCTutorialEntry::Title() { return TEXT("New here? Learn the basics in about ten minutes"); }

FString TCTutorialEntry::NewRoomCode()
{
	// public-lobby.js code(): crypto.getRandomValues(new Uint8Array(6)) as two hex digits each
	// FPlatformMisc::CreateGuid: on Linux a UUIDv7 whose C and D come from getrandom(); its timestamp half (A, B) is not
	// used, so the 48 bits are D and the low half of C (below the variant bits)
	FGuid G;
	FPlatformMisc::CreateGuid(G);
	const uint32 Parts[2] = { G.D, G.C & 0xffffu };
	return FString::Printf(TEXT("%08x%04x"), Parts[0], Parts[1] & 0xffffu);
}

TSharedRef<FJsonObject> TCTutorialEntry::Listing()
{
	TSharedRef<FJsonObject> L = MakeShared<FJsonObject>();
	L->SetBoolField(TEXT("public"), false);
	L->SetStringField(TEXT("title"), TEXT("Tutorial"));
	L->SetBoolField(TEXT("tutorial"), true);
	return L;
}

bool TCTutorialEntry::IsTutorialListing(const FJsonObject* Listing)
{
	bool bTutorial = false;
	return Listing && Listing->TryGetBoolField(TEXT("tutorial"), bTutorial) && bTutorial;
}

bool TCTutorialEntry::FromCommandLine(const TCHAR* Cmd, FString& InOutRoom, TSharedPtr<FJsonObject>& OutListing)
{
	if (!Cmd || !FParse::Param(Cmd, TEXT("TCTutorial"))) return false;
	FString Given;
	if (!FParse::Value(Cmd, TEXT("TCRoom="), Given)) InOutRoom = NewRoomCode();
	OutListing = Listing();
	return true;
}

// ---------------------------------------------------------------------------------------------------------------------
// Progress as the snapshots tell it

void FTCTutorialProgress::Reset()
{
	bTutorial = bFinished = false;
	CurStep = -1; CurSteps = 0; WinnerTeam = -2; MatchId = -1;
	CurGoal.Reset(); Reason.Reset();
	History.Reset();
	ScriptLines.Reset();
	OtherLines.Reset();
	Pending.Reset();
	LastTick.Reset();
}

void FTCTutorialProgress::OnStart(const FTCMatchState& S)
{
	// a reconnect to the same match keeps what was seen; a new match starts over
	if (S.MatchId != MatchId) { Reset(); MatchId = S.MatchId; }
}

void FTCTutorialProgress::OnSnapshot(const FTCMatchState& S, const FJsonObject* Raw)
{
	if (!S.bHasMatch) return;
	if (LastTick.IsSet() && S.Tick <= LastTick.GetValue()) return; // a duplicate or older snapshot says nothing new
	LastTick = S.Tick;
	const bool bNow = S.ModeRow.bPresent && S.ModeRow.Kind == TEXT("tutorial");
	if (!bNow && !bTutorial) return;
	bTutorial = true;
	const int32 Step = S.ModeRow.Step.Get(-1), Steps = S.ModeRow.Steps.Get(0);
	if (bNow && (Step != CurStep || S.ModeRow.Goal != CurGoal))
	{
		CurStep = Step; CurSteps = Steps; CurGoal = S.ModeRow.Goal;
		FTCTutorialStepSeen& E = History.AddDefaulted_GetRef();
		E.Step = Step; E.Steps = Steps; E.Goal = CurGoal; E.Tick = S.Tick;
		const TArray<FTCTutorialStep>& Script = TCTutorialData::Steps();
		E.bReferenceGoal = Script.IsValidIndex(Step) && Script[Step].Goal.Equals(CurGoal, ESearchCase::CaseSensitive);
		Pending.Add(FString::Printf(TEXT("tutorial: step %d / %d at tick %d: %s (%s)"), Step + 1, Steps, S.Tick, *CurGoal,
			E.bReferenceGoal ? TEXT("the script's goal") : TEXT("NOT the script's goal for this step")));
	}
	// the say shots of this snapshot (shared/tutorial.js pushes a step's lines when it begins, from tick 40)
	const TArray<TSharedPtr<FJsonValue>>* Shots = nullptr;
	if (Raw && Raw->TryGetArrayField(TEXT("shots"), Shots))
		for (const TSharedPtr<FJsonValue>& V : *Shots)
		{
			const TSharedPtr<FJsonObject>* O = nullptr;
			FString K, Text;
			if (!V.IsValid() || !V->TryGetObject(O) || !(*O)->TryGetStringField(TEXT("k"), K) || K != TEXT("say")) continue;
			(*O)->TryGetStringField(TEXT("text"), Text);
			FString Shown;
			if (!FTCLocale::SayText(**O, Shown)) Shown = Text;
			Shown = FTCLocale::T(Shown);
			// a step's lines leave one tick after it begins (stepTutorial splices mode.lines before it checks done()), so a
			// step that lasts one tick has its lines arrive under the next step: kept as arrived, and by their own step
			if (History.Num()) { History.Last().Said.Add(Text); History.Last().Shown.Add(Shown); }
			int32 LS = -1, LL = -1;
			const bool bScript = TCTutorialData::FindLine(Text, LS, LL);
			if (bScript) { if (ScriptLines.Num() <= LS) ScriptLines.SetNum(LS + 1); ScriptLines[LS].Add(Text); }
			else OtherLines.Add(Text);
			Pending.Add(FString::Printf(TEXT("tutorial: Sgt. Hollis at tick %d (%s): %s%s"), S.Tick,
				bScript ? *FString::Printf(TEXT("step %d line %d"), LS + 1, LL + 1) : TEXT("not a script line"), *Text, Shown != Text ? *FString::Printf(TEXT(" | shown: %s"), *Shown) : TEXT("")));
		}
	if (!bFinished && S.Winner >= -1 && S.End.bPresent)
	{
		bFinished = true; WinnerTeam = S.Winner; Reason = S.End.Reason;
		Pending.Add(FString::Printf(TEXT("tutorial: decided at tick %d: winner team %d, reason %s"), S.Tick, WinnerTeam, *Reason));
		Pending.Add(TEXT("tutorial: ") + Verdict());
	}
}

int32 FTCTutorialProgress::LinesSaid() const
{
	int32 N = OtherLines.Num();
	for (const TArray<FString>& L : ScriptLines) N += L.Num();
	return N;
}

const TArray<FString>& FTCTutorialProgress::LinesOf(int32 Step) const
{
	static const TArray<FString> None;
	return ScriptLines.IsValidIndex(Step) ? ScriptLines[Step] : None;
}

TArray<int32> FTCTutorialProgress::StepsNotShown() const
{
	TArray<int32> Out;
	for (int32 I = 0; I < TCTutorialData::Steps().Num(); I++) if (!History.ContainsByPredicate([I](const FTCTutorialStepSeen& E) { return E.Step == I; })) Out.Add(I);
	return Out;
}

bool FTCTutorialProgress::MatchesScript() const
{
	const TArray<FTCTutorialStep>& Script = TCTutorialData::Steps();
	if (!History.Num() || History[0].Step != 0 || History.Last().Step != Script.Num() - 1 || OtherLines.Num()) return false;
	for (int32 I = 0; I < History.Num(); I++)
	{
		const FTCTutorialStepSeen& E = History[I];
		if (!E.bReferenceGoal || E.Steps != Script.Num() || (I && E.Step <= History[I - 1].Step)) return false;
	}
	for (int32 I = 0; I < Script.Num(); I++) if (LinesOf(I) != Script[I].Say) return false;
	return bFinished && WinnerTeam == 0 && Reason == TEXT("tutorial");
}

FString FTCTutorialProgress::Verdict() const
{
	const TArray<FTCTutorialStep>& Script = TCTutorialData::Steps();
	int32 Lines = 0;
	for (const FTCTutorialStep& St : Script) Lines += St.Say.Num();
	TArray<FString> Problems, Unshown;
	for (int32 I = 0; I < History.Num(); I++)
	{
		const FTCTutorialStepSeen& E = History[I];
		if (I && E.Step <= History[I - 1].Step) Problems.Add(FString::Printf(TEXT("step %d shown after step %d"), E.Step + 1, History[I - 1].Step + 1));
		if (!E.bReferenceGoal) Problems.Add(FString::Printf(TEXT("step %d's goal is not the script's"), E.Step + 1));
	}
	for (int32 I = 0; I < Script.Num(); I++)
		if (LinesOf(I) != Script[I].Say) Problems.Add(FString::Printf(TEXT("step %d's lines: %d of %d"), I + 1, LinesOf(I).Num(), Script[I].Say.Num()));
	if (OtherLines.Num()) Problems.Add(FString::Printf(TEXT("%d line(s) not in the script"), OtherLines.Num()));
	for (const int32 I : StepsNotShown()) Unshown.Add(FString::FromInt(I + 1));
	const FString Head = FString::Printf(TEXT("%d of %d steps shown by a snapshot%s, %d of %d lines, %s"), History.Num(), Script.Num(),
		Unshown.Num() ? *FString::Printf(TEXT(" (step %s began and ended between two snapshots; its lines arrived with the next)"), *FString::Join(Unshown, TEXT(", "))) : TEXT(""),
		LinesSaid(), Lines, bFinished ? *FString::Printf(TEXT("decided (winner team %d, %s)"), WinnerTeam, *Reason) : TEXT("not decided"));
	return MatchesScript() ? TEXT("matches the script: ") + Head : FString::Printf(TEXT("does NOT match the script: %s%s%s"), *Head, Problems.Num() ? TEXT("; ") : TEXT(""), *FString::Join(Problems, TEXT("; ")));
}

// ---------------------------------------------------------------------------------------------------------------------
// CLI-127: the Controls sheet at the first match

const TCHAR* const FTCControlsOnboarding::SettingsSection = TEXT("ThreeCrossroads");
const TCHAR* const FTCControlsOnboarding::SettingsKey = TEXT("ControlsSeen");

bool FTCControlsOnboarding::Seen() const
{
	if (ReadSeen) return ReadSeen();
	FString V;
	return GConfig && GConfig->GetString(SettingsSection, SettingsKey, V, GGameUserSettingsIni) && V == TEXT("1");
}

bool FTCControlsOnboarding::OnStart(bool bOperative)
{
	// main.js receiveStart: if (!operative && localStorage 'ww2-controls-seen' !== '1') openControls(true)
	if (bOperative || Seen()) return false;
	const bool bAllowUnattended = AllowUnattended.IsSet() ? AllowUnattended.GetValue() : FParse::Param(FCommandLine::Get(), TEXT("TCOnboarding"));
	if (FApp::IsUnattended() && !bAllowUnattended) return false;
	bOnboarding = true;
	bManual = false;
	return true;
}

bool FTCControlsOnboarding::OnPointerDown()
{
	// controlsSheet pointerdown: only while it opened as onboarding; the press is swallowed and the sheet closes
	return bOnboarding;
}

void FTCControlsOnboarding::OnClosed()
{
	// controlsSheet close: onboarding stores 'ww2-controls-seen' = '1'
	if (bOnboarding)
	{
		if (WriteSeen) WriteSeen();
		else if (GConfig) { GConfig->SetString(SettingsSection, SettingsKey, TEXT("1"), GGameUserSettingsIni); GConfig->Flush(false, GGameUserSettingsIni); }
	}
	bOnboarding = false;
	bManual = false;
}

// ---------------------------------------------------------------------------------------------------------------------
// -TCTutorialDrive (verification): Tools/tutorial/policy.mjs in C++, from this seat's snapshot only

namespace TCTutorialDrive
{
	TSharedRef<FJsonObject> Orders(const TCHAR* T, const TArray<TTuple<int32, double, double>>& Rows)
	{
		TSharedRef<FJsonObject> C = MakeShared<FJsonObject>();
		C->SetStringField(TEXT("t"), T);
		TArray<TSharedPtr<FJsonValue>> A;
		for (const TTuple<int32, double, double>& R : Rows)
			A.Add(MakeShared<FJsonValueArray>(TArray<TSharedPtr<FJsonValue>>{ MakeShared<FJsonValueNumber>(R.Get<0>()), MakeShared<FJsonValueNumber>(R.Get<1>()), MakeShared<FJsonValueNumber>(R.Get<2>()) }));
		C->SetArrayField(TEXT("orders"), A);
		return C;
	}
	TArray<TSharedPtr<FJsonValue>> IdArray(const TArray<const FTCUnit*>& Who)
	{
		TArray<TSharedPtr<FJsonValue>> A;
		for (const FTCUnit* U : Who) A.Add(MakeShared<FJsonValueNumber>(U->Id));
		return A;
	}
}

TArray<TSharedRef<FJsonObject>> FTCTutorialDriver::Decide(const FTCMatchState& S, const FTCUnitTable* Table)
{
	using namespace TCTutorialDrive;
	TArray<TSharedRef<FJsonObject>> Out;
	if (!S.CanOrder() || !S.ModeRow.bPresent || S.ModeRow.Kind != TEXT("tutorial") || !S.ModeRow.Step.IsSet()) return Out;
	const int32 T = S.Tick, Step = S.ModeRow.Step.GetValue();
	auto Structure = [Table](const FString& Type)
	{
		if (const FTCUnitDef* D = Table ? Table->Find(Type) : nullptr) return D->bStructure;
		return Type == TEXT("hq") || Type == TEXT("bunker") || Type == TEXT("depot") || Type == TEXT("barracks") || Type == TEXT("motorpool") || Type == TEXT("airfield");
	};
	TArray<const FTCUnit*> Mine, Foes;
	TArray<int32> Ids;
	S.Units.GenerateKeyArray(Ids);
	Ids.Sort(); // the server's row order is by id; the policy reads rows in that order
	for (const int32 Id : Ids)
	{
		const FTCUnit& U = S.Units[Id];
		if (U.Hp <= 0 || Structure(U.Type)) continue;
		if (U.Owner == S.You) Mine.Add(&U);
		else if (S.IsFoe(U.Owner)) Foes.Add(&U);
	}
	if (Memo.Step != Step) { Memo.Step = Step; Memo.SentAt = -1000000000; Memo.StepAt = T; Memo.bBuy = Memo.bPlace = Memo.bRetreat = false; }
	auto Every = [this, T](int32 N) { if (T - Memo.SentAt < N) return false; Memo.SentAt = T; return true; };
	auto At = [](int32 X, int32 Y) { return TCTutorialData::CellCentre(FIntPoint(X, Y)); };
	auto Spread = [&At](const TArray<const FTCUnit*>& Who, int32 X, int32 Y)
	{
		TArray<TTuple<int32, double, double>> Rows;
		for (int32 I = 0; I < Who.Num(); I++) { const FVector2D P = At(X + (I % 3) - 1, Y + (I / 3) * 2 - 1); Rows.Add(MakeTuple(Who[I]->Id, P.X, P.Y)); }
		return Rows;
	};
	auto Nearest = [](const FTCUnit* From, const TArray<const FTCUnit*>& List)
	{
		const FTCUnit* Best = nullptr;
		double BestD = TNumericLimits<double>::Max();
		for (const FTCUnit* U : List) { const double D = FMath::Square(U->X - From->X) + FMath::Square(U->Z - From->Z); if (D < BestD) { BestD = D; Best = U; } }
		return Best;
	};
	auto AttackSeen = [&](const TArray<const FTCUnit*>& Who)
	{
		if (!Foes.Num() || !Who.Num()) return false;
		const FTCUnit* Target = Nearest(Who[0], Foes);
		TSharedRef<FJsonObject> C = MakeShared<FJsonObject>();
		C->SetStringField(TEXT("t"), TEXT("attack"));
		C->SetArrayField(TEXT("ids"), IdArray(Who));
		C->SetNumberField(TEXT("target"), Target->Id);
		Out.Add(C);
		return true;
	};
	auto OfType = [&Mine](const TCHAR* Type, bool bIs) { return Mine.FilterByPredicate([Type, bIs](const FTCUnit* U) { return (U->Type == Type) == bIs; }); };
	// each rifle squad off cooldown throws at the nearest enemy (aimed: the server walks it into range); the rest attack
	auto Busy = [this, T](const FTCUnit* U) { const int32* Asked = Memo.Nade.Find(U->Id); return Asked && T - *Asked < 160; };
	auto Grenades = [&]()
	{
		for (const FTCUnit* U : Mine)
		{
			if (U->Type != TEXT("rifle") || U->Cd != 0 || (U->Flags & TCFlags::Retreating) || Busy(U)) continue;
			const FTCUnit* F = Nearest(U, Foes);
			Memo.Nade.Add(U->Id, T);
			TSharedRef<FJsonObject> C = MakeShared<FJsonObject>();
			C->SetStringField(TEXT("t"), TEXT("ability"));
			C->SetArrayField(TEXT("ids"), { MakeShared<FJsonValueNumber>(U->Id) });
			C->SetNumberField(TEXT("x"), F->X); C->SetNumberField(TEXT("z"), F->Z);
			Out.Add(C);
		}
		AttackSeen(Mine.FilterByPredicate([&Busy](const FTCUnit* U) { return !Busy(U); }));
	};
	switch (Step)
	{
	case 0: if (Every(100)) Out.Add(Orders(TEXT("move"), Spread(Mine, 16, 22))); break;
	case 1: if (Every(40) && !AttackSeen(Mine)) Out.Add(Orders(TEXT("amove"), Spread(Mine, 23, 22))); break;
	case 2: if (Every(100)) Out.Add(Orders(TEXT("move"), Spread(Mine, 34, 22))); break;
	case 3:
		if (!Memo.bBuy)
		{
			Memo.bBuy = true;
			TSharedRef<FJsonObject> C = MakeShared<FJsonObject>();
			C->SetStringField(TEXT("t"), TEXT("buy")); C->SetStringField(TEXT("unit"), TEXT("at"));
			Out.Add(C);
		}
		break;
	case 4:
	{
		if (!Every(30)) break;
		const TArray<const FTCUnit*> Guns = OfType(TEXT("at"), true), Rest = OfType(TEXT("at"), false);
		if (!Memo.bPlace) { Memo.bPlace = true; Out.Add(Orders(TEXT("move"), Spread(Rest, 28, 26))); }
		if (!Guns.Num()) break; // still in training
		if (!AttackSeen(Guns)) Out.Add(Orders(TEXT("amove"), Spread(Guns, 40, 22)));
		break;
	}
	case 5:
	{
		if (!Every(30)) break;
		if (!Foes.Num()) { Out.Add(Orders(TEXT("amove"), Spread(Mine, 41, 22))); break; }
		Grenades();
		break;
	}
	case 6:
		if (!Memo.bRetreat && Mine.Num())
		{
			Memo.bRetreat = true;
			const FTCUnit* const* Rifle = Mine.FindByPredicate([](const FTCUnit* U) { return U->Type == TEXT("rifle"); });
			TSharedRef<FJsonObject> C = MakeShared<FJsonObject>();
			C->SetStringField(TEXT("t"), TEXT("retreat"));
			C->SetArrayField(TEXT("ids"), { MakeShared<FJsonValueNumber>(Rifle ? (*Rifle)->Id : Mine[0]->Id) });
			Out.Add(C);
		}
		break;
	case 7:
		if (Every(40))
		{
			const FVector2D P = At(63, 17);
			TSharedRef<FJsonObject> C = MakeShared<FJsonObject>();
			C->SetStringField(TEXT("t"), TEXT("support")); C->SetStringField(TEXT("kind"), TEXT("artillery"));
			C->SetNumberField(TEXT("x"), P.X); C->SetNumberField(TEXT("z"), P.Y);
			Out.Add(C);
		}
		break;
	case 8:
		if (T - Memo.StepAt < 200 || !Every(40)) break; // the barrage lands first
		if (!Foes.Num()) { Out.Add(Orders(TEXT("amove"), Spread(Mine, 62, 22))); break; }
		Grenades(); // a squad left in the stone house shrugs off bullets
		break;
	default: break;
	}
	Memo.Count += Out.Num();
	return Out;
}

