void ATCGameMode::TutorialSwitches(const TCHAR* Cmd)
{
	bTutorialDrive = FParse::Param(Cmd, TEXT("TCTutorialDrive"));
	FParse::Value(Cmd, TEXT("TCTutorialShots="), TutorialShotDir);
	if (!FParse::Value(Cmd, TEXT("TCTutorialShotTag="), TutorialShotTag)) TutorialShotTag = FTCLocale::Code();
	FParse::Value(Cmd, TEXT("TCTutorialButtonAfter="), TutorialButtonAfter);
	ScenarioText.GroundHeight = [this](double X, double Z) { return Terrain ? (double)Terrain->HeightAt(X, Z) : 0.0; };
	UE_LOG(LogTC, Log, TEXT("tutorial and scenario guidance: script %s (%d steps), scenario text %s%s%s"), TCTutorialData::ReferencePin, TCTutorialData::Steps().Num(), FTCScenarioText::ReferencePin,
		bTutorialDrive ? TEXT(", -TCTutorialDrive plays this seat from its own snapshots") : TEXT(""), TutorialShotDir.IsEmpty() ? TEXT("") : *FString::Printf(TEXT(", step captures to %s"), *TutorialShotDir));
}

void ATCGameMode::TutorialStart()
{
	Tutorial.OnStart(State);
	TutorialDriver.Reset();
	ScenarioText.Reset();
	TutorialShotStep = -2; TutorialShotAt = -1.0; bTutorialEndShot = false; TutorialStartAt = FPlatformTime::Seconds();
	// CLI-127, client/main.js receiveStart: the Controls sheet opens as onboarding until it has been dismissed once
	ATCPlayerController* PC = Cast<ATCPlayerController>(GetWorld()->GetFirstPlayerController());
	if (PC && !State.bSpectator && Onboarding.OnStart(false))
	{
		if (!PC->bControlsSheetOpen) PC->RunUi(ETCUiAction::ControlsSheet); // openControls: cancelInput, then the sheet
		UE_LOG(LogTC, Log, TEXT("controls onboarding: the Controls sheet opens at this match start (a press on it closes it; seen is stored then)"));
	}
	else UE_LOG(LogTC, Log, TEXT("controls onboarding: %s"), Onboarding.Seen() ? TEXT("seen before, the sheet stays closed") : State.bSpectator ? TEXT("a spectator: not opened") : TEXT("an unattended run: not opened (-TCOnboarding opens it)"));
}

void ATCGameMode::TutorialSnapshot(const FJsonObject& M)
{
	Tutorial.OnSnapshot(State, &M);
	for (const FString& L : Tutorial.TakeLog()) UE_LOG(LogTC, Log, TEXT("%s"), *L);
	// objectives.js snapshot: the goal box, the collapse banners and the damaged buildings (ranked by the camera now)
	FTCPlumeCamera Cam;
	const ATCPlayerController* PC = Cast<ATCPlayerController>(GetWorld()->GetFirstPlayerController());
	if (PC && PC->PlayerCameraManager)
	{
		const FVector L = PC->PlayerCameraManager->GetCameraLocation();
		Cam.bValid = true;
		Cam.Position = FVector2D(L.X / 100.0, L.Y / 100.0);
		Cam.Dist = PC->ViewDistance();
		Cam.Project = [PC](double X, double Y, double Z)
		{
			FVector2D Px;
			int32 W = 0, H = 0;
			PC->GetViewportSize(W, H);
			if (W <= 0 || H <= 0 || !PC->ProjectWorldLocationToScreen(ATCTerrain::ToWorld(X, Z, Y), Px)) return FVector(0.0, 0.0, 2.0); // behind: out
			return FVector(2.0 * Px.X / W - 1.0, 1.0 - 2.0 * Px.Y / H, 0.0);
		};
	}
	const FString BannerBefore = ScenarioText.Banner();
	ScenarioText.OnSnapshot(State, &UnitTable, Cam);
	if (ScenarioText.BannerShown() && ScenarioText.Banner() != BannerBefore) UE_LOG(LogTC, Log, TEXT("objective banner at tick %d: %s"), State.Tick, *ScenarioText.Banner());
	// -TCTutorialDrive: this seat's orders from this snapshot
	if (bTutorialDrive)
		for (const TSharedRef<FJsonObject>& C : TutorialDriver.Decide(State, &UnitTable))
		{
			const bool bSent = SendCommand(C);
			if (!bSent) UE_LOG(LogTC, Warning, TEXT("tutorial drive: %s not sent: %s"), *C->GetStringField(TEXT("t")), *LastSendProblem());
		}
}

void ATCGameMode::TutorialFrame(float Dt)
{
	const double Now = FPlatformTime::Seconds();
	// objectives.js frame: the banner's 4 s and the damaged buildings' smoke and fire (fx.js plume)
	const TArray<FTCPlumeBurst> Bursts = ScenarioText.Frame(Dt);
#if defined(TC_HAS_FX_PLUME)
	if (Effects) for (const FTCPlumeBurst& B : Bursts) Effects->Fx.Plume(B.Kind, B.X, B.Y, B.Z, B.Radius);
#endif
	TutorialPlumeBursts += Bursts.Num();
	// -TCTutorialButtonAfter=N: the lobby's Tutorial button, N s after the lobby showed (a capture first)
	if (TutorialButtonAfter > 0.0 && !bTutorialButtonPressed && State.RoomState == TEXT("lobby") && !State.bHasMatch)
	{
		if (TutorialLobbyAt < 0) TutorialLobbyAt = Now;
		if (!TutorialShotDir.IsEmpty() && !bTutorialLobbyShot && Now - TutorialLobbyAt >= TutorialButtonAfter - 1.0)
		{
			bTutorialLobbyShot = true;
			FScreenshotRequest::RequestScreenshot(FPaths::Combine(TutorialShotDir, FString::Printf(TEXT("tutorial-%s-lobby-button.png"), *TutorialShotTag)), true, false);
		}
		if (Now - TutorialLobbyAt >= TutorialButtonAfter)
		{
			bTutorialButtonPressed = true;
			ATCPlayerController* PC = Cast<ATCPlayerController>(GetWorld()->GetFirstPlayerController());
			UE_LOG(LogTC, Log, TEXT("tutorial: pressing the lobby's Tutorial button (%s)"), PC && PC->RunUi(ETCUiAction::Tutorial) ? TEXT("taken") : TEXT("refused"));
		}
	}
	if (TutorialShotDir.IsEmpty() || !State.bHasMatch) return;
	// -TCOnboarding with captures: the sheet as it opened, then a press on it (the path a click on it takes)
	ATCPlayerController* PC = Cast<ATCPlayerController>(GetWorld()->GetFirstPlayerController());
	if (PC && Onboarding.IsOnboarding() && TutorialStartAt > 0)
	{
		if (!bTutorialOnboardShot && Now - TutorialStartAt >= 2.0)
		{
			bTutorialOnboardShot = true;
			FScreenshotRequest::RequestScreenshot(FPaths::Combine(TutorialShotDir, FString::Printf(TEXT("tutorial-%s-controls-onboarding.png"), *TutorialShotTag)), true, false);
		}
		else if (bTutorialOnboardShot && Now - TutorialStartAt >= 4.0)
		{
			const bool bTaken = PC->OnboardingPress();
			UE_LOG(LogTC, Log, TEXT("controls onboarding: a press on the sheet %s; sheet %s, seen %s"), bTaken ? TEXT("closed it") : TEXT("was not taken"), PC->bControlsSheetOpen ? TEXT("open") : TEXT("closed"), Onboarding.Seen() ? TEXT("stored") : TEXT("not stored"));
		}
		return;
	}
	// one capture per step, 3 s after it began (its lines are up), and one of the ending
	if (Tutorial.IsTutorial() && Tutorial.Step() != TutorialShotStep && !Tutorial.IsFinished()) { TutorialShotStep = Tutorial.Step(); TutorialShotAt = Now + 3.0; bTutorialJumped = false; }
	// Space: the camera jumps to the newest alert (client/alerts.js newest, the Hollis line's cell), as a player would
	if (TutorialShotAt > 0 && !bTutorialJumped && Now >= TutorialShotAt - 1.0)
	{
		bTutorialJumped = true;
		FVector2D At;
		const bool bAlert = NewestAlertAt(At);
		const bool bTaken = PC && PC->RunUi(ETCUiAction::Alert);
		UE_LOG(LogTC, Log, TEXT("tutorial: Space (newest alert) %s%s"), bTaken ? TEXT("taken") : TEXT("refused"), bAlert ? *FString::Printf(TEXT(": the camera jumps to (%.1f, %.1f); now looking at (%.1f, %.1f)"), At.X, At.Y, PC->ViewFocus().X, PC->ViewFocus().Y) : TEXT(": no alert"));
	}
	if (TutorialShotAt > 0 && Now >= TutorialShotAt)
	{
		TutorialShotAt = -1.0;
		const FString File = FPaths::Combine(TutorialShotDir, FString::Printf(TEXT("tutorial-%s-step-%d-of-%d.png"), *TutorialShotTag, Tutorial.Step() + 1, Tutorial.Steps()));
		FScreenshotRequest::RequestScreenshot(File, true, false);
		UE_LOG(LogTC, Log, TEXT("tutorial: capture of step %d requested: %s"), Tutorial.Step() + 1, *File);
	}
	if (Tutorial.IsFinished() && !bTutorialEndShot)
	{
		if (TutorialEndAt < 0) TutorialEndAt = Now;
		if (Now - TutorialEndAt >= 2.0)
		{
			bTutorialEndShot = true;
			const FString File = FPaths::Combine(TutorialShotDir, FString::Printf(TEXT("tutorial-%s-victory.png"), *TutorialShotTag));
			FScreenshotRequest::RequestScreenshot(File, true, false);
			UE_LOG(LogTC, Log, TEXT("tutorial: capture of the ending requested: %s"), *File);
		}
	}
}

void ATCGameMode::TutorialClear()
{
	if (Tutorial.IsTutorial()) UE_LOG(LogTC, Log, TEXT("tutorial: cleared (%s; %d plume bursts drawn this match)"), *Tutorial.Verdict(), TutorialPlumeBursts);
	Tutorial.Reset();
	TutorialDriver.Reset();
	ScenarioText.Reset();
	TutorialPlumeBursts = 0; TutorialEndAt = -1.0;
}

void ATCGameMode::EnterTutorialRoom()
{
	// client/public-lobby.js: enter(code(), { public: false, title: 'Tutorial', tutorial: true }) navigates the page to a
	// new room; here the old room's socket closes and a new one opens with the listing in its hello
	FTCConnection::FSettings S = BaseSettings;
	S.Room = TCTutorialEntry::NewRoomCode();
	S.Listing = TCTutorialEntry::Listing();
	S.bSpectate = false;
	FTCTokenRequest R = BaseTokenRequest;
	R.Room = S.Room;
	R.bSpectate = false;
	R.TokenFile.Reset(); // client/room-session.js: a token per room (the default per-room file, not -TCTokenFile's)
	UE_LOG(LogTC, Log, TEXT("tutorial: leaving room %s for a new private Tutorial room %s"), *State.RoomCode, *S.Room);
	if (Connection) { Connection->OnMessage = nullptr; Connection->OnOpened = nullptr; Connection->OnText = nullptr; Connection->Stop(); Connection.Reset(); }
	RustShadow.End();
	TokenStore.Reset();
	State.ClearMatch();
	State.RoomState.Reset(); State.RoomCode.Reset(); State.Roster.Reset(); State.Spectators.Reset();
	State.bSpectator = false; State.bAmHost = false; State.LobbySeat = -1;
	ClearMatchPresentation();
	TutorialClear();
	TutorialLobbyAt = -1.0;
	Connect(S, R);
}
